#[test]
fn test_try_infer_type_quick_squash_returns_sprop() {
    let env = Environment::new();
    let tc = TypeChecker::with_mode(&env, CleanMode::Impredicative);

    let squash = Expr::from_kind(ExprKind::Squash(std::sync::Arc::new(Expr::prop())));
    let full_ty = tc
        .infer_type(&squash)
        .expect("Squash(Prop) should type check in Impredicative mode");

    assert_eq!(
        full_ty,
        Expr::from_kind(ExprKind::SProp),
        "full infer_type should classify Squash(_) as SProp"
    );
    assert_eq!(
        tc.try_infer_type_quick(&squash),
        Some(full_ty),
        "quick type inference must preserve Squash instead of peeling to the inner type"
    );
}

