// --- Dependent application proof irrelevance (regression for #1383) ---

#[test]
fn test_proof_irrelevance_dependent_application() {
    // Regression test for #1383: try_infer_type_quick must instantiate the Pi
    // body with the argument for dependent types. Without instantiation,
    // BVar(0) in the result type causes is_type_in_prop to return false,
    // disabling proof irrelevance for dependent applications.
    //
    // Key: the Pi body must literally be BVar(0) so that without instantiation,
    // try_infer_type_quick falls through to None on the dangling BVar.
    //
    // Setup: P : Prop, f : Π (x : Prop), x, g : Π (x : Prop), x
    // f and g have type Π (x : Sort(0)), BVar(0) — body IS BVar(0)
    // typeof(App(f, P)) = BVar(0)[P/0] = P (a Prop)
    // typeof(App(g, P)) = BVar(0)[P/0] = P (a Prop)
    // Without fix: typeof(App(f, P)) = BVar(0) → is_type_in_prop → None → false
    // With fix: typeof(App(f, P)) = P → is_type_in_prop → true
    //
    // We test is_def_eq(App(f, P), App(g, P)) directly — both are App expressions
    // so try_infer_type_quick goes through the App case.
    use crate::env::Declaration;

    let mut env = Environment::new();

    // P : Prop
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("P"),
        level_params: vec![],
        type_: Expr::prop(),
    })
    .unwrap();

    // f : Π (x : Prop), x — a "proof selector" with truly dependent type
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("f"),
        level_params: vec![],
        type_: Expr::pi(BinderInfo::Default, Expr::prop(), Expr::bvar(0)),
    })
    .unwrap();

    // g : Π (x : Prop), x — different axiom, same dependent type
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("g"),
        level_params: vec![],
        type_: Expr::pi(BinderInfo::Default, Expr::prop(), Expr::bvar(0)),
    })
    .unwrap();

    let p_const = Expr::const_(Name::from_string("P"), vec![]);
    let f_const = Expr::const_(Name::from_string("f"), vec![]);
    let g_const = Expr::const_(Name::from_string("g"), vec![]);

    // App(f, P) : P and App(g, P) : P — both are proofs of P (a Prop)
    let f_of_p = Expr::app(f_const, p_const.clone());
    let g_of_p = Expr::app(g_const, p_const);

    let tc = TypeChecker::new(&env);

    // f P and g P should be def_eq: both are proofs of the same Prop (P).
    // This requires try_infer_type_quick's App case to instantiate BVar(0)
    // with P, yielding P instead of a dangling BVar(0).
    assert!(
        tc.is_def_eq(&f_of_p, &g_of_p),
        "Proof irrelevance for dependent application: f P and g P both prove P"
    );
}

#[test]
fn test_no_proof_irrelevance_dependent_type_application() {
    // Negative test: f : Π (x : Type), x, g : Π (x : Type), x
    // The Pi body is BVar(0) (like the positive test), but the domain is
    // Type (Sort 1), not Prop. After instantiation with A (a Type),
    // typeof(App(f, A)) = A. typeof(A) = Type = Sort(1), not Sort(0).
    // So A is NOT in Prop → no proof irrelevance.
    use crate::env::Declaration;

    let mut env = Environment::new();

    // A : Type
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("A"),
        level_params: vec![],
        type_: Expr::type_(),
    })
    .unwrap();

    // f : Π (x : Type), x — dependent type into Type, not Prop
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("f"),
        level_params: vec![],
        type_: Expr::pi(BinderInfo::Default, Expr::type_(), Expr::bvar(0)),
    })
    .unwrap();

    // g : Π (x : Type), x — different axiom, same type
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("g"),
        level_params: vec![],
        type_: Expr::pi(BinderInfo::Default, Expr::type_(), Expr::bvar(0)),
    })
    .unwrap();

    let a_const = Expr::const_(Name::from_string("A"), vec![]);
    let f_const = Expr::const_(Name::from_string("f"), vec![]);
    let g_const = Expr::const_(Name::from_string("g"), vec![]);

    // App(f, A) : A and App(g, A) : A — both have type A (a Type, not Prop)
    let f_of_a = Expr::app(f_const, a_const.clone());
    let g_of_a = Expr::app(g_const, a_const);

    let tc = TypeChecker::new(&env);

    // f A and g A should NOT be def_eq: both have type A which is Type, not Prop
    assert!(
        !tc.is_def_eq(&f_of_a, &g_of_a),
        "No proof irrelevance for Type-valued dependent application"
    );
}

