#[test]
fn test_is_type_in_prop_sort_match() {
    // Kill mutant: delete match arm Expr::from_kind(ExprKind::Sort(_)) in is_type_in_prop (line 947)
    let env = Environment::new();
    let tc = TypeChecker::new(&env);

    // A Sort itself is NOT in Prop (it's a type, not a proof)
    // is_type_in_prop checks if the TYPE of the expression is in Prop

    // Sort 0 (Prop) has type Sort 1 (Type), so it's NOT in Prop
    assert!(!tc.is_type_in_prop(&Expr::prop()));

    // Sort 1 (Type) has type Sort 2, so it's NOT in Prop
    assert!(!tc.is_type_in_prop(&Expr::type_()));

    // A Sort should always return false (tested by the match arm)
}

// --- Projection proof irrelevance (regression for #1387) ---

/// Regression test for #1387: try_infer_type_quick must handle Proj expressions
/// so proof irrelevance works for structure field projections.
///
/// Setup: And : Prop → Prop → Prop (structure with one constructor)
/// And.intro : (P Q : Prop) → P → Q → And P Q
/// h1, h2 : And P Q (two different proofs)
/// Proj(And, 0, h1) and Proj(And, 0, h2) should be def_eq (both are proofs of P)
#[test]
fn test_proof_irrelevance_proj() {
    use crate::env::Declaration;
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};

    let mut env = Environment::new();

    let and_name = Name::from_string("And");

    // And : Prop → Prop → Prop
    let and_type = Expr::pi(
        BinderInfo::Default,
        Expr::prop(),                                              // P : Prop
        Expr::pi(BinderInfo::Default, Expr::prop(), Expr::prop()), // Q : Prop → Prop
    );

    // And.intro : (P Q : Prop) → P → Q → And P Q
    // Parameters: P, Q (2 params)
    // Fields: proof of P, proof of Q (2 fields)
    let ctor_type = Expr::pi(
        BinderInfo::Default,
        Expr::prop(), // P
        Expr::pi(
            BinderInfo::Default,
            Expr::prop(), // Q
            Expr::pi(
                BinderInfo::Default,
                Expr::bvar(1), // proof of P
                Expr::pi(
                    BinderInfo::Default,
                    Expr::bvar(1), // proof of Q
                    Expr::app(
                        Expr::app(Expr::const_(and_name.clone(), vec![]), Expr::bvar(3)),
                        Expr::bvar(2),
                    ),
                ),
            ),
        ),
    );

    let decl = InductiveDecl {
        level_params: vec![],
        num_params: 2, // P and Q are parameters
        types: vec![InductiveType {
            name: and_name.clone(),
            type_: and_type,
            constructors: vec![Constructor {
                name: Name::from_string("And.intro"),
                type_: ctor_type,
            }],
        }],
    };

    env.add_inductive(decl).unwrap();

    // Define P : Prop and Q : Prop
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("P"),
        level_params: vec![],
        type_: Expr::prop(),
    })
    .unwrap();
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("Q"),
        level_params: vec![],
        type_: Expr::prop(),
    })
    .unwrap();

    let p_const = Expr::const_(Name::from_string("P"), vec![]);
    let q_const = Expr::const_(Name::from_string("Q"), vec![]);

    // h1 : And P Q (first proof)
    let and_pq = Expr::app(
        Expr::app(Expr::const_(and_name.clone(), vec![]), p_const.clone()),
        q_const.clone(),
    );
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("h1"),
        level_params: vec![],
        type_: and_pq.clone(),
    })
    .unwrap();

    // h2 : And P Q (second proof)
    env.add_decl(Declaration::Axiom {
        name: Name::from_string("h2"),
        level_params: vec![],
        type_: and_pq,
    })
    .unwrap();

    let h1 = Expr::const_(Name::from_string("h1"), vec![]);
    let h2 = Expr::const_(Name::from_string("h2"), vec![]);

    // Proj(And, 0, h1) and Proj(And, 0, h2) — both project the P-proof
    let proj_h1 = Expr::proj(and_name.clone(), 0, h1);
    let proj_h2 = Expr::proj(and_name.clone(), 0, h2);

    let tc = TypeChecker::new(&env);

    // Both projections are proofs of P (a Prop).
    // With the #1387 fix, try_infer_type_quick handles Proj and determines
    // that the projected type is P (which is in Prop), enabling proof irrelevance.
    assert!(
        tc.is_def_eq(&proj_h1, &proj_h2),
        "Proof irrelevance for Proj: And.1 h1 and And.1 h2 both prove P"
    );
}

/// Test try_infer_type_quick returns Some for valid Proj expressions.
/// This directly tests the Proj arm added in #1387.
#[test]
fn test_try_infer_type_quick_proj() {
    use crate::inductive::{Constructor, InductiveDecl, InductiveType};

    let mut env = Environment::new();

    let pair = Name::from_string("Pair");

    // Pair : Type → Type → Type
    let pair_type = Expr::pi(
        BinderInfo::Default,
        Expr::type_(),
        Expr::pi(BinderInfo::Default, Expr::type_(), Expr::type_()),
    );

    // mk : (A B : Type) → A → B → Pair A B
    let mk_type = Expr::pi(
        BinderInfo::Default,
        Expr::type_(),
        Expr::pi(
            BinderInfo::Default,
            Expr::type_(),
            Expr::pi(
                BinderInfo::Default,
                Expr::bvar(1), // A
                Expr::pi(
                    BinderInfo::Default,
                    Expr::bvar(1), // B
                    Expr::app(
                        Expr::app(Expr::const_(pair.clone(), vec![]), Expr::bvar(3)),
                        Expr::bvar(2),
                    ),
                ),
            ),
        ),
    );

    let decl = InductiveDecl {
        level_params: vec![],
        num_params: 2,
        types: vec![InductiveType {
            name: pair.clone(),
            type_: pair_type,
            constructors: vec![Constructor {
                name: Name::from_string("Pair.mk"),
                type_: mk_type,
            }],
        }],
    };

    env.add_inductive(decl).unwrap();

    // Create a term of type Pair Nat Nat (using axiom for simplicity)
    let nat_name = Name::from_string("Nat");
    let nat_const = Expr::const_(nat_name.clone(), vec![]);
    let pair_nat_nat = Expr::app(
        Expr::app(Expr::const_(pair.clone(), vec![]), nat_const.clone()),
        nat_const.clone(),
    );

    env.add_decl_unchecked(crate::env::Declaration::Axiom {
        name: Name::from_string("p"),
        level_params: vec![],
        type_: pair_nat_nat,
    });

    // Also need Nat in the environment for type lookup
    env.add_decl_unchecked(crate::env::Declaration::Axiom {
        name: nat_name,
        level_params: vec![],
        type_: Expr::type_(),
    });

    let p = Expr::const_(Name::from_string("p"), vec![]);

    // Proj(Pair, 0, p) should infer type Nat
    let proj0 = Expr::proj(pair.clone(), 0, p.clone());
    // Proj(Pair, 1, p) should infer type Nat
    let proj1 = Expr::proj(pair, 1, p);

    let tc = TypeChecker::new(&env);

    let ty0 = tc.try_infer_type_quick(&proj0);
    assert!(
        ty0.is_some(),
        "try_infer_type_quick should handle Proj (field 0)"
    );
    assert_eq!(
        ty0.unwrap(),
        nat_const.clone(),
        "Proj 0 of Pair Nat Nat should have type Nat"
    );

    let ty1 = tc.try_infer_type_quick(&proj1);
    assert!(
        ty1.is_some(),
        "try_infer_type_quick should handle Proj (field 1)"
    );
    assert_eq!(
        ty1.unwrap(),
        nat_const,
        "Proj 1 of Pair Nat Nat should have type Nat"
    );
}
